let key = expirations.insert(msg, Duration::from_secs(60));

tokio::select! {
    Some(expired) = expirations.next() => {
        dead_letter(expired.get_ref()).await;   // expired: never dispatched
    }
    result = handle_incoming(&mut rx) => {
        expirations.remove(&key);               // consumed in time: cancel expiry
        result
    }
}
